// MIT. Import original captured HTTP bytes without issuing another provider request.
import { join, resolve } from 'node:path';
import { digest, identity, readPrivate, privateDirectory, fault, object } from '../postgres/publisher/files.mjs';
import { CENSUS_API, MAX_INPUT_BYTES, MAX_RESPONSE_BYTES, inputAddresses, metadata, parseBatchResponse, only } from './source.mjs';

export const RECORDING_SCHEMA = 'stellar-forge.census-geocoder-capture.v1';
function exchange(value, body, { path, method = 'GET', benchmark = null, vintage = null, submittedSha256 = null }) {
  if (!object(value) || value.schema !== 'stellar-forge.census-geocoder-http.v1') throw fault('GEOCODER_CAPTURE_HTTP_SCHEMA');
  const expected = new URL(CENSUS_API + path);
  if (path === '/vintages') expected.searchParams.set('benchmark', String(benchmark));
  if (value.requestedUrl !== expected.href || value.url !== expected.href || value.method !== method ||
      value.status !== 200 || value.sha256 !== digest(body) || value.bytes !== body.length ||
      (value.benchmark ?? null) !== benchmark || (value.vintage ?? null) !== vintage ||
      (value.submittedSha256 ?? null) !== submittedSha256 ||
      typeof value.contentType !== 'string' ||
      !Number.isFinite(Date.parse(value.startedAt)) || !Number.isFinite(Date.parse(value.receivedAt)) ||
      Date.parse(value.receivedAt) < Date.parse(value.startedAt))
    throw fault('GEOCODER_CAPTURE_HTTP_BINDING', 'Retain the exact successful Census request, response and submitted CSV binding.');
  return value;
}
/** Fixed filenames are deliberate: a capture is data, never a path/URL program. */
export async function readGeocoderRecording(directory) {
  if (typeof directory !== 'string' || !directory) throw fault('GEOCODER_CAPTURE_DIRECTORY');
  directory = resolve(directory); await privateDirectory(directory);
  const manifestBytes = await readPrivate(join(directory, 'capture.json'), 65536);
  const manifest = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(manifestBytes));
  only(manifest, ['schema', 'label', 'header', 'returnType', 'benchmark', 'vintage', 'inputSha256', 'submittedSha256']);
  if (manifest.schema !== RECORDING_SCHEMA || typeof manifest.label !== 'string' ||
      !manifest.label.trim() || manifest.label.length > 128 ||
      !['locations', 'geographies'].includes(manifest.returnType) ||
      typeof manifest.header !== 'boolean' || !/^\d{1,12}$/.test(manifest.benchmark) ||
      manifest.returnType === 'geographies' && !/^\d{1,12}$/.test(manifest.vintage) ||
      manifest.returnType === 'locations' && manifest.vintage !== null)
    throw fault('GEOCODER_CAPTURE_MANIFEST');
  const originals = { 'capture.json': manifestBytes };
  for (const name of ['input.csv', 'submitted.csv'])
    originals[name] = await readPrivate(join(directory, name), MAX_INPUT_BYTES);
  const input = inputAddresses(originals['input.csv'], { header: manifest.header });
  const submitted = inputAddresses(originals['submitted.csv'], { header: false });
  if (manifest.inputSha256 !== digest(originals['input.csv']) ||
      manifest.submittedSha256 !== digest(originals['submitted.csv']) ||
      identity(input.records) !== identity(submitted.records))
    throw fault('GEOCODER_CAPTURE_INPUT_CHANGED', 'The captured submission must contain the same reviewed address records.');
  const options = {};
  for (const kind of ['benchmarks', ...(manifest.returnType === 'geographies' ? ['vintages'] : [])]) {
    originals[kind + '.json'] = await readPrivate(join(directory, kind + '.json'), 1024 * 1024);
    originals[kind + '-http.json'] = await readPrivate(join(directory, kind + '-http.json'), 65536);
    const http = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(originals[kind + '-http.json']));
    exchange(http, originals[kind + '.json'], { path: '/' + kind, benchmark: kind === 'vintages' ? manifest.benchmark : null });
    options[kind] = { raw: originals[kind + '.json'], httpBytes: originals[kind + '-http.json'], http,
      parsed: metadata(originals[kind + '.json'], kind, manifest.benchmark) };
  }
  const benchmark = options.benchmarks.parsed.options.find(value => value.id === manifest.benchmark);
  const vintage = manifest.returnType === 'geographies' ?
    options.vintages.parsed.options.find(value => value.id === manifest.vintage) : null;
  if (!benchmark || manifest.returnType === 'geographies' && !vintage)
    throw fault('GEOCODER_CAPTURE_SELECTION', 'The original metadata must contain the exact benchmark and vintage used.');
  originals['response.csv'] = await readPrivate(join(directory, 'response.csv'), MAX_RESPONSE_BYTES);
  originals['http.json'] = await readPrivate(join(directory, 'http.json'), 65536);
  const http = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(originals['http.json']));
  exchange(http, originals['response.csv'], { path: '/' + manifest.returnType + '/addressbatch', method: 'POST',
    benchmark: manifest.benchmark, vintage: manifest.vintage, submittedSha256: manifest.submittedSha256 });
  const parsed = parseBatchResponse(originals['response.csv'], input.records, manifest.returnType);
  const files = Object.fromEntries(Object.entries(originals).map(([name, value]) => [name, { bytes: value.length, sha256: digest(value) }]));
  return { directory, manifest, originals, input, submitted, benchmark, vintage, options, http, parsed,
    recordingSha256: identity(files), files };
}

// MIT. Local authenticated operator over one original geocoder workspace.
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { randomBytes, timingSafeEqual } from 'node:crypto';
import { fault } from '../postgres/publisher/files.mjs';

async function readBody(req) {
  if (!/^application\/json(?:\s*;|$)/i.test(req.headers['content-type'] ?? ''))
    throw fault('JSON_REQUIRED', 'Send application/json.', 415);
  const chunks = []; let size = 0;
  for await (const chunk of req) {
    size += chunk.length; if (size > 8 * 1024 * 1024) throw fault('REQUEST_TOO_LARGE', 'The input exceeds 8 MiB.', 413);
    chunks.push(chunk);
  }
  try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(Buffer.concat(chunks))); }
  catch { throw fault('JSON_INVALID'); }
}
export async function startGeocoderServer({ workspace, port = 0 } = {}) {
  if (!workspace || typeof workspace.act !== 'function' || !Number.isInteger(port) || port < 0 || port > 65535)
    throw new TypeError('Open a geocoder workspace and choose a valid local port.');
  const assets = new Map(await Promise.all([
    ['/', 'index.html', 'text/html; charset=utf-8'], ['/app.mjs', 'app.mjs', 'text/javascript; charset=utf-8'],
    ['/style.css', 'style.css', 'text/css; charset=utf-8']
  ].map(async ([path, name, type]) => [path, { bytes: await readFile(new URL('./public/' + name, import.meta.url)), type }])));
  const token = randomBytes(32).toString('hex'), authorization = Buffer.from('Bearer ' + token);
  let origin, closing;
  const server = createServer((req, res) => {
    function send(status, value, type = 'application/json; charset=utf-8', filename) {
      if (res.destroyed || res.writableEnded) return;
      const output = Buffer.isBuffer(value) ? value : Buffer.from(JSON.stringify(value));
      const headers = { 'content-type': type, 'content-length': output.length, 'cache-control': 'no-store',
        'x-content-type-options': 'nosniff', 'referrer-policy': 'no-referrer',
        'content-security-policy': "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' blob:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'" };
      if (filename) headers['content-disposition'] = 'attachment; filename="' + filename.replace(/[^A-Za-z0-9_.-]/g, '_') + '"';
      res.writeHead(status, headers); res.end(output);
    }
    async function dispatch() {
      if (req.headers.host !== new URL(origin).host || req.headers.origin && req.headers.origin !== origin ||
          req.headers['sec-fetch-site'] === 'cross-site') throw fault('LOCAL_ORIGIN_REQUIRED', 'Use the printed local operator URL.', 403);
      if (typeof req.url !== 'string' || !req.url.startsWith('/') || req.url.startsWith('//')) throw fault('INVALID_REQUEST_TARGET');
      const url = new URL(req.url, origin);
      if (req.method === 'GET' && !url.search && assets.has(url.pathname)) {
        const asset = assets.get(url.pathname); return send(200, asset.bytes, asset.type);
      }
      const supplied = Buffer.from(req.headers.authorization ?? '');
      if (supplied.length !== authorization.length || !timingSafeEqual(supplied, authorization))
        throw fault('SESSION_REQUIRED', 'Reopen the private session URL printed by the local command.', 401);
      if (req.method === 'GET' && url.pathname === '/api/state') return send(200, await workspace.status());
      if (req.method === 'GET' && url.pathname === '/api/batch') return send(200, await workspace.inspectBatch(url.searchParams.get('id'), {
        attemptId: url.searchParams.get('attempt') || undefined, status: url.searchParams.get('status') || 'all',
        offset: Number(url.searchParams.get('offset') ?? 0), limit: Number(url.searchParams.get('limit') ?? 100) }));
      if (req.method === 'GET' && url.pathname === '/api/download') {
        const file = await workspace.download(url.searchParams.get('kind'), url.searchParams.get('id'));
        return send(200, file.bytes, file.contentType, file.filename);
      }
      if (req.method === 'POST' && url.pathname === '/api/action') {
        const input = await readBody(req);
        if (!input || typeof input.action !== 'string' || Object.keys(input).some(key => !['action', 'payload'].includes(key)))
          throw fault('ACTION_REQUIRED');
        const result = await workspace.act(input.action, input.payload ?? {});
        return send(200, { result, state: await workspace.status() });
      }
      throw fault('NOT_FOUND', 'Choose an available operator action.', 404);
    }
    dispatch().catch(error => send([400,401,403,404,409,413,415,422,502].includes(error.status) ? error.status : 422,
      { error: error.code ?? 'GEOCODER_OPERATION_FAILED', message: error.message }));
  });
  server.requestTimeout = 920000; server.headersTimeout = 15000; server.keepAliveTimeout = 1000;
  try { await new Promise((done, reject) => { server.once('error', reject); server.listen(port, '127.0.0.1', done); }); }
  catch (error) { await workspace.close(); throw error; }
  origin = 'http://127.0.0.1:' + server.address().port;
  return { server, workspace, url: origin, operatorUrl: origin + '/#' + token, close() {
    closing ??= (async () => {
      const connections = new Promise((done, reject) => {
        server.close(error => error ? reject(error) : done()); server.closeIdleConnections?.();
      });
      const result = await Promise.allSettled([workspace.close(), connections]);
      const failure = result.find(item => item.status === 'rejected'); if (failure) throw failure.reason;
    })();
    return closing;
  } };
}

// MIT. The official Census address-batch contract, using the original CSV parser.
import { createCsvRecordParser } from '../dataset-handler.mjs';
import { csvLine } from '../postgres/publisher/plan.mjs';
import { digest, fault, object } from '../postgres/publisher/files.mjs';

export const CENSUS_API = 'https://geocoding.geo.census.gov/geocoder';
export const API_GUIDE = 'https://geocoding.geo.census.gov/geocoder/Geocoding_Services_API.html';
export const MAX_INPUT_BYTES = 5_000_000;
export const MAX_RESPONSE_BYTES = 32 * 1024 * 1024;
export const COORDINATE_MEANING = 'Census MAF/TIGER address-range interpolation: approximate longitude/latitude, not a verified building location.';
export const COLUMNS = Object.freeze({
  record_id: { type: 'string', nullable: false },
  input_address: { type: 'string', nullable: false },
  match_status: { type: 'string', nullable: false },
  match_type: { type: 'string', nullable: true },
  matched_address: { type: 'string', nullable: true },
  longitude: { type: 'number', nullable: true },
  latitude: { type: 'number', nullable: true },
  coordinate_text: { type: 'string', nullable: true },
  tigerline_id: { type: 'string', nullable: true },
  tigerline_side: { type: 'string', nullable: true },
  state_fips: { type: 'string', nullable: true },
  county_fips: { type: 'string', nullable: true },
  tract_code: { type: 'string', nullable: true },
  block_code: { type: 'string', nullable: true },
  tract_geoid: { type: 'string', nullable: true },
  block_geoid: { type: 'string', nullable: true }
});
export function only(value, keys, message = 'Unsupported action fields.') {
  if (!object(value) || Object.keys(value).some(key => !keys.includes(key)))
    throw fault('GEOCODER_INPUT_INVALID', message);
}
export function csvRecords(bytes, { maximum = MAX_RESPONSE_BYTES, maxRecords = 10000 } = {}) {
  if (!Buffer.isBuffer(bytes) || bytes.length > maximum)
    throw fault('GEOCODER_FILE_SIZE', 'Choose a CSV within its displayed byte limit.');
  const result = [], parser = createCsvRecordParser(row => {
    if (result.length >= maxRecords) throw fault('GEOCODER_RECORD_LIMIT', 'Census accepts at most 10,000 addresses in one batch.');
    result.push(row);
  }, 65536);
  parser.feed(new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes));
  parser.end();
  return result;
}
export function inputAddresses(original, { header = false } = {}) {
  if (typeof header !== 'boolean') throw fault('GEOCODER_HEADER_CHOICE', 'Choose whether the CSV has a header.');
  const records = csvRecords(original, { maximum: MAX_INPUT_BYTES, maxRecords: 10001 });
  if (header) {
    const names = records.shift()?.map(value => value.toLowerCase().trim()) ?? [];
    const required = ['id', 'street', 'city', 'state', 'zip'];
    if (names.length < 5 || names.length > 6 || required.some((name, i) => names[i] !== name) ||
        names.length === 6 && names[5] !== 'urbanization')
      throw fault('GEOCODER_HEADER_INVALID', 'Use id,street,city,state,zip and optional urbanization, in that order.');
  }
  if (!records.length || records.length > 10000)
    throw fault('GEOCODER_RECORD_LIMIT', 'Choose 1–10,000 address records.');
  const seen = new Set();
  for (const [index, row] of records.entries()) {
    if (![5, 6].includes(row.length) || !row[0]?.trim() || !row[1]?.trim() ||
        row.some(value => /[\x00-\x1f\x7f]/.test(value)))
      throw fault('GEOCODER_ADDRESS_INVALID', 'Record ' + (index + 1) + ' needs an ID, street and five or six fields without control characters.');
    if (row[0].length > 256 || seen.has(row[0]))
      throw fault('GEOCODER_ID_INVALID', 'Retain distinct address IDs of at most 256 characters.');
    if ((!row[2].trim() || !row[3].trim()) && !row[4].trim())
      throw fault('GEOCODER_LOCALITY_REQUIRED', 'Record ' + row[0] + ' needs city and state, or ZIP.');
    if (row[5]?.trim() && row[3].toUpperCase() !== 'PR')
      throw fault('GEOCODER_URBANIZATION_INVALID', 'Urbanization is the sixth field for Puerto Rico addresses.');
    seen.add(row[0]);
  }
  const submitted = Buffer.from(records.map(csvLine).join(''));
  if (submitted.length > MAX_INPUT_BYTES)
    throw fault('GEOCODER_BATCH_SIZE', 'The submitted Census batch exceeds the 5,000,000-byte local limit.');
  return { records, submitted, count: records.length, originalSha256: digest(original),
    submittedSha256: digest(submitted), originalBytes: original.length, submittedBytes: submitted.length };
}
export function metadata(bytes, kind, selectedBenchmark) {
  const value = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
  const key = kind === 'benchmarks' ? 'benchmarks' : 'vintages', names = new Set();
  if (!object(value) || !Array.isArray(value[key]) || !value[key].length || value[key].length > 256 ||
      kind === 'vintages' && String(value.selectedBenchmark) !== String(selectedBenchmark))
    throw fault('GEOCODER_DISCOVERY_INVALID', 'The official metadata does not match this selection.');
  const options = value[key].map(item => {
    const name = item[kind === 'benchmarks' ? 'benchmarkName' : 'vintageName'];
    if (!object(item) || !/^[0-9]{1,12}$/.test(String(item.id)) || typeof name !== 'string' ||
        !name || name.length > 128 || names.has(String(item.id)))
      throw fault('GEOCODER_DISCOVERY_INVALID', 'The official selection list contains an invalid or repeated ID.');
    names.add(String(item.id));
    return { ...item, id: String(item.id) };
  });
  return { value, options };
}
export function parseBatchResponse(bytes, input, returnType = 'geographies') {
  if (!['locations', 'geographies'].includes(returnType)) throw fault('GEOCODER_RETURN_TYPE');
  const original = new Map(input.map(row => [row[0], row])), parsed = csvRecords(bytes), byId = new Map();
  const counts = { Match: 0, No_Match: 0, Tie: 0, Exact: 0, Non_Exact: 0 };
  for (const cells of parsed) {
    if (cells.length < 3 || cells.length > (returnType === 'geographies' ? 12 : 8) ||
        !original.has(cells[0]) || byId.has(cells[0]) ||
        !['Match', 'No_Match', 'Tie'].includes(cells[2]))
      throw fault('GEOCODER_RESPONSE_RECORD', 'The response must contain one recognized result for every submitted address ID.');
    const padded = [...cells]; while (padded.length < 12) padded.push('');
    const [id, inputAddress, status, type, matched, coordinates, tiger, side, state, county, tract, block] = padded;
    let longitude = null, latitude = null;
    if (status === 'Match') {
      const pair = coordinates.split(',');
      if (!['Exact', 'Non_Exact'].includes(type) || !matched || !tiger || !['L', 'R'].includes(side) ||
          pair.length !== 2 || pair.some(value => !/^-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(value.trim())))
        throw fault('GEOCODER_MATCH_INVALID', 'A matched result is missing its original match or coordinate fields.');
      [longitude, latitude] = pair.map(Number);
      if (!Number.isFinite(longitude) || Math.abs(longitude) > 180 || !Number.isFinite(latitude) || Math.abs(latitude) > 90)
        throw fault('GEOCODER_COORDINATE_INVALID', 'The returned longitude/latitude is outside its native range.');
      if (returnType === 'geographies' && [state, county, tract, block].some((value, i) => value && !new RegExp('^\\d{' + [2,3,6,4][i] + '}$').test(value)))
        throw fault('GEOCODER_GEOGRAPHY_INVALID', 'Geography codes must retain their original zero-padded Census widths.');
      counts[type]++;
    } else if (padded.slice(3).some(value => value !== '')) {
      throw fault('GEOCODER_UNMATCHED_FIELDS', 'An unmatched or tied result unexpectedly contains match fields; retain and inspect the original response.');
    }
    const tractGeoid = state && county && tract ? state + county + tract : null;
    const row = { record_id: id, input_address: inputAddress, match_status: status,
      match_type: type || null, matched_address: matched || null, longitude, latitude,
      coordinate_text: coordinates || null, tigerline_id: tiger || null, tigerline_side: side || null,
      state_fips: state || null, county_fips: county || null, tract_code: tract || null, block_code: block || null,
      tract_geoid: tractGeoid, block_geoid: tractGeoid && block ? tractGeoid + block : null };
    counts[status]++; byId.set(id, row);
  }
  if (byId.size !== input.length)
    throw fault('GEOCODER_RESPONSE_INCOMPLETE', 'The original batch response omitted submitted address IDs.');
  return { rows: input.map(row => byId.get(row[0])), counts,
    responseSha256: digest(bytes), responseBytes: bytes.length, coordinateMeaning: COORDINATE_MEANING };
}
/** Fetch only the official endpoint; callers retain the response before interpretation. */
export async function censusRequest(path, { method = 'GET', submitted, benchmark, vintage,
  signal, timeoutMs = 300000, fetch: fetcher = globalThis.fetch } = {}) {
  if (!['/benchmarks', '/vintages', '/locations/addressbatch', '/geographies/addressbatch'].includes(path))
    throw fault('GEOCODER_ENDPOINT_INVALID');
  const url = new URL(CENSUS_API + path);
  let body;
  if (path === '/vintages') url.searchParams.set('benchmark', String(benchmark));
  if (method === 'POST') {
    if (!path.endsWith('/addressbatch') || !Buffer.isBuffer(submitted)) throw fault('GEOCODER_BATCH_REQUEST_INVALID');
    body = new FormData();
    body.set('addressFile', new Blob([submitted], { type: 'text/csv' }), 'addresses.csv');
    body.set('benchmark', String(benchmark));
    if (path.startsWith('/geographies/')) body.set('vintage', String(vintage));
  } else if (method !== 'GET' || path.endsWith('/addressbatch')) throw fault('GEOCODER_METHOD_INVALID');
  if (!Number.isInteger(timeoutMs) || timeoutMs < 1000 || timeoutMs > 900000) throw fault('GEOCODER_TIMEOUT_INVALID');
  const timeout = AbortSignal.timeout(timeoutMs), joined = signal ? AbortSignal.any([signal, timeout]) : timeout;
  const startedAt = new Date().toISOString();
  const response = await fetcher(url.href, { method, body, signal: joined, redirect: 'error',
    headers: { accept: method === 'POST' ? 'text/csv,text/plain;q=0.9' : 'application/json',
      'user-agent': 'Starforge-Census-Geocoder/1.0 (+https://github.com/woahwhattheheck/public-commons-sprint-2026)' } });
  const maximum = method === 'POST' ? MAX_RESPONSE_BYTES : 1024 * 1024;
  const declared = response.headers.get('content-length');
  if (declared && /^\d+$/.test(declared) && Number(declared) > maximum) {
    await response.body?.cancel();
    throw fault('GEOCODER_RESPONSE_SIZE', 'The official response exceeds its retained size limit.');
  }
  const chunks = []; let length = 0;
  try {
    for await (const chunk of response.body ?? []) {
      length += chunk.length;
      if (length > maximum) throw fault('GEOCODER_RESPONSE_SIZE');
      chunks.push(Buffer.from(chunk));
    }
  } catch (error) { await response.body?.cancel().catch(() => {}); throw error; }
  const output = Buffer.concat(chunks);
  return { bytes: output, exchange: { schema: 'stellar-forge.census-geocoder-http.v1',
    requestedUrl: url.href, url: response.url || url.href, method, status: response.status,
    contentType: response.headers.get('content-type'), etag: response.headers.get('etag'),
    lastModified: response.headers.get('last-modified'), retryAfter: response.headers.get('retry-after'),
    startedAt, receivedAt: new Date().toISOString(), bytes: output.length, sha256: digest(output),
    submittedSha256: submitted ? digest(submitted) : null,
    benchmark: benchmark == null ? null : String(benchmark), vintage: vintage == null ? null : String(vintage) } };
}

// MIT. One retained Census intake; existing publishers own release and buyer actions.
import { lstat } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { randomUUID } from 'node:crypto';
import { loadDatasetConfig } from '../dataset-handler.mjs';
import { bytes, digest, identity, readPrivate, readJson, createFile, atomicJson,
  privateDirectory, acquireWorkspace, syncDirectory, fault, stamp } from '../postgres/publisher/files.mjs';
import { CENSUS_API, MAX_INPUT_BYTES, MAX_RESPONSE_BYTES, COLUMNS, COORDINATE_MEANING,
  only, inputAddresses, metadata, parseBatchResponse, censusRequest } from './source.mjs';
import { reviewSelection, createEdition, reopenEdition, copyEdition, writeExact } from './edition.mjs';
import { readGeocoderRecording } from './recording.mjs';

const SCHEMA = 'stellar-forge.census-geocoder-workspace.v1';
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const clone = value => structuredClone(value);
const publicError = error => ({ code: typeof error.code === 'string' ? error.code : 'GEOCODER_OPERATION_FAILED', message: error.message });
async function absent(path) { try { await lstat(path); return false; } catch (e) { if (e.code === 'ENOENT') return true; throw e; } }
function key(value) { if (typeof value !== 'string' || !UUID.test(value)) throw fault('GEOCODER_ID_REQUIRED'); return value; }
function text(value, name, limit = 128) {
  if (typeof value !== 'string' || !value.trim() || value.length > limit || /[\x00-\x1f\x7f]/.test(value))
    throw fault('GEOCODER_TEXT_REQUIRED', 'Enter ' + name + '.');
  return value;
}
export async function openGeocoderWorkspace({ directory, create = false, fetch: fetcher = globalThis.fetch } = {}) {
  if (typeof directory !== 'string' || !directory) throw fault('GEOCODER_DIRECTORY_REQUIRED');
  directory = resolve(directory);
  const index = join(directory, 'workspace.json');
  if (create && !await absent(index)) throw fault('GEOCODER_WORKSPACE_EXISTS', 'Reopen this existing workspace.');
  await privateDirectory(directory, create); const release = await acquireWorkspace(directory);
  let state, active = null, closing = null, closed = false, publisher = null, publisherOpening = null;
  const pending = new Set();
  const save = async () => { state.updatedAt = stamp(); await atomicJson(directory, 'workspace.json', state); };
  const selected = (list, id, label) => {
    const entry = state[list].find(item => item.id === key(id));
    if (!entry) throw fault('GEOCODER_NOT_FOUND', 'Choose a retained ' + label + '.', 404);
    return entry;
